SELECT id, title, company, role, location, job_level, tech_stack, created_on, listing_expires_on, salary_min, salary_max, salary_currency, is_salary_negotiable, is_internship, source_url
FROM clean_jobs
ORDER BY created_on DESC NULLS LAST;

SELECT id, title, company, role, tech_stack, location, source_url, job_level, listing_expires_on, created_on, is_internship, salary_min, salary_max, salary_currency, is_salary_negotiable
FROM clean_jobs
WHERE description ILIKE '%remote%' OR description ILIKE '%từ xa%' OR description ILIKE '%work from home%' OR description ILIKE '%làm việc từ xa%';
